-- ================================================================
--  UNIVERSITY DATABASE
--  Run this file in MySQL CMD:
--  mysql -u root -p < university_setup.sql
-- ================================================================

-- Step 1: Create and use database
DROP DATABASE IF EXISTS university_db;
CREATE DATABASE university_db;
USE university_db;

-- Step 2: Create table
CREATE TABLE students (
    student_id    INT PRIMARY KEY,
    roll_no       VARCHAR(30),
    student_name  VARCHAR(100),
    college       VARCHAR(50),
    branch        VARCHAR(20),
    semester      INT,
    sgpa          DECIMAL(4,2),
    cgpa          DECIMAL(4,2),
    attendance    INT,
    backlogs      INT,
    fees_paid     INT,
    scholarship   VARCHAR(3),
    placed        VARCHAR(3),
    package_lpa   DECIMAL(5,1)
);

-- Step 3: Insert 2000 records






















-- ================================================================
-- VERIFY: Run these after loading
-- ================================================================
SELECT COUNT(*) AS total_records FROM students;

SELECT college, COUNT(*) AS students
FROM students
GROUP BY college
ORDER BY students DESC;

SELECT branch, COUNT(*) AS students
FROM students
GROUP BY branch;

commit ;